from django.db import migrations, models

# Duraciones de los servicios de ejemplo; cualquier otro principal arranca en el mínimo (5 h)
# y el administrador lo ajusta desde la pantalla de servicios.
CONOCIDOS = {'Flete urbano': 5, 'Mudanza local': 10, 'Mudanza nacional': 48}
MINIMO = 5


def cargar_duraciones(apps, schema_editor):
    Servicio = apps.get_model('usuarios', 'Servicio')
    DetallePedido = apps.get_model('usuarios', 'DetallePedido')
    for s in Servicio.objects.filter(Categoria='Principal'):
        s.Duracion_horas = CONOCIDOS.get(s.Tipo_servicio, MINIMO)
        s.save(update_fields=['Duracion_horas'])
    # Cada pedido toma la duración de su servicio principal
    for d in DetallePedido.objects.filter(idServicio__Categoria='Principal').select_related('idPedido', 'idServicio'):
        d.idPedido.duracion_horas = d.idServicio.Duracion_horas
        d.idPedido.save(update_fields=['duracion_horas'])


class Migration(migrations.Migration):

    dependencies = [
        ('usuarios', '0010_personal_pedido'),
    ]

    operations = [
        migrations.AddField(
            model_name='pedido',
            name='duracion_horas',
            field=models.PositiveSmallIntegerField(db_column='Duracion_horas', default=5, verbose_name='Duración estimada (horas)'),
        ),
        migrations.AddField(
            model_name='servicio',
            name='Duracion_horas',
            field=models.PositiveSmallIntegerField(blank=True, db_column='Duracion_horas', null=True, verbose_name='Duración estimada (horas)'),
        ),
        migrations.RunPython(cargar_duraciones, migrations.RunPython.noop),
    ]
